.darma-loader-tw-toggle-switch { position: relative; width: var(--loader-size, 90px); height: calc(var(--loader-size, 90px) * .55); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #3b82f6) 25%, transparent); animation: darma-loader-tw-toggle-switch-twTrack calc(var(--loader-speed, 1s) * 2) ease-in-out infinite; }
.darma-loader-tw-toggle-switch .darma-loader-tw-toggle-switch__knob { position: absolute; top: 10%; left: 3%; width: calc(var(--loader-size, 90px) * .45); height: 80%; border-radius: 9999px; background: var(--loader-color, #3b82f6); animation: darma-loader-tw-toggle-switch-twKnob calc(var(--loader-speed, 1s) * 2) cubic-bezier(.4, 0, .2, 1) infinite; }
@keyframes darma-loader-tw-toggle-switch-twKnob { 0%, 10% { left: 3%; } 45%, 55% { left: 52%; } 90%, 100% { left: 3%; } }
@keyframes darma-loader-tw-toggle-switch-twTrack { 0%, 10%, 90%, 100% { filter: saturate(.4); } 45%, 55% { filter: saturate(1.5); } }

